/* From Uiverse.io by ahmed150up - Tags: checkbox, star */
.__UIV_SCOPE__ input[type="checkbox"] {
  display: none;
}

.__UIV_SCOPE__ label svg {
  width: 44px;
  height: 44px;
  fill: none;
  stroke: #000;
  stroke-width: 2px;
}

.__UIV_SCOPE__ input[type="checkbox"]:checked + label svg {
  fill: #FFC107;
  animation: pop_42 0.5s ease-out;
}

@keyframes pop_42 {
  0% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.5);
  }

  100% {
    transform: scale(1);
  }
}
